#include <iostream>

template<typename T>
class Array {
public:
    void mf() { std::cout << "Array of " << typeid(T).name() << std::endl; }
};

// Explicit instantiation definition for Array<int>
template class Array<int>;  // Compiler generates code for Array<int> here

// Explicit instantiation declaration for Array<char>
extern template class Array<char>;  // Compiler does not generate code; expects it elsewhere
